sys_script_include.script:
function TargetInstancePluginActivate(grInstance,strPluginId)
{
	var GetValue = x_snc_devtools.GetValue;
	var GetStringValue = x_snc_devtools.GetStringValue;
	var IsValidSysId = x_snc_devtools.IsValidSysId;
	var IsValidPluginId = x_snc_devtools.IsValidPluginId;

	strPluginId = GetStringValue(strPluginId);

	if (IsValidPluginId(strPluginId) == false)
	{
		return false;
	}

	var result = TargetInstanceRequest(grInstance,'sn_cicd/plugin/'+strPluginId+'/activate','','post');

	var strStatus = GetValue(result,'result','status');
	if (strStatus == '2')
	{
		return true;
	}

	var strProgressId = GetValue(result,'result','links','progress','id');

	if (IsValidSysId(strProgressId) == false)
	{
		return false;
	}

	return strProgressId;	
}
